const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function getInfoAsync(obj) {
    return new Promise((resolve, reject) => {
      obj.getInfo((res, err) => {
        if (err) reject(err);
        else resolve(res);
      });
    });
  }

  try {
    // 1. Geometry & Time Definitions
    const dateStart = '2024-10-01';
    const dateEnd = '2024-11-01';
    const scale = 10000; // 10 km
    const maxPixels = 1e9;

    const countries = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017');
    const auGeom = countries.filter(ee.Filter.eq('country_na', 'Australia')).geometry();
    const idGeom = countries.filter(ee.Filter.eq('country_na', 'Indonesia')).geometry();

    // 2. Data Acquisition & Check
    const offl = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_CO').filterDate(dateStart, dateEnd);
    const offlCount = await getInfoAsync(offl.size());
    let coll = offl;
    let datasetUsed = 'OFFL';

    if (!offlCount || offlCount === 0) {
      const ntri = ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_CO').filterDate(dateStart, dateEnd);
      const ntriCount = await getInfoAsync(ntri.size());
      if (!ntriCount || ntriCount === 0) {
        console.log(`Date: ${dateStart} to ${dateEnd}`);
        console.log(`OFFL images: ${offlCount || 0}`);
        console.log(`NRTI images: ${ntriCount || 0}`);
        console.log('C1');
        return;
      } else {
        coll = ntri;
        datasetUsed = 'NRTI';
      }
    }

    // 3. Processing: QA mask and temporal mean
    const masked = coll.map(function(img) {
      const qa = img.select('qa_value').gt(0.5);
      return img.updateMask(qa).select('CO_column_number_density');
    });
    const meanImg = masked.mean();

    const ones = ee.Image.constant(1).rename('ones');

    // Australia stats
    const auCount = ee.Number(meanImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: auGeom,
      scale: scale,
      maxPixels: maxPixels
    }).get('CO_column_number_density'));
    const auTotal = ee.Number(ones.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: auGeom,
      scale: scale,
      maxPixels: maxPixels
    }).get('ones'));
    const auMean = ee.Number(meanImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: auGeom,
      scale: scale,
      maxPixels: maxPixels
    }).get('CO_column_number_density'));

    // Indonesia stats
    const idCount = ee.Number(meanImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: idGeom,
      scale: scale,
      maxPixels: maxPixels
    }).get('CO_column_number_density'));
    const idTotal = ee.Number(ones.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: idGeom,
      scale: scale,
      maxPixels: maxPixels
    }).get('ones'));
    const idMean = ee.Number(meanImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: idGeom,
      scale: scale,
      maxPixels: maxPixels
    }).get('CO_column_number_density'));

    // Evaluate all at once
    const results = await getInfoAsync(ee.Dictionary({
      offlCount: offl.size(),
      ntriCount: ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_CO').filterDate(dateStart, dateEnd).size(),
      auCount: auCount, auTotal: auTotal, auMean: auMean,
      idCount: idCount, idTotal: idTotal, idMean: idMean
    }));

    // 4. Validation & Final Answer
    const usedOfflCount = results.offlCount;
    const usedNtriCount = results.ntriCount;
    console.log(`Date: ${dateStart} to ${dateEnd}`);
    if (datasetUsed === 'OFFL') {
      console.log(`OFFL images: ${usedOfflCount} (used) | NRTI images: ${usedNtriCount}`);
    } else {
      console.log(`OFFL images: ${usedOfflCount} | NRTI images: ${usedNtriCount} (used)`);
    }

    const auCnt = results.auCount || 0;
    const idCnt = results.idCount || 0;
    const auTot = results.auTotal || 0;
    const idTot = results.idTotal || 0;
    if (auCnt === 0 || idCnt === 0 || auTot === 0 || idTot === 0) {
      console.log(`Australia valid px: ${auCnt}/${auTot} (0.0%) mean: null`);
      console.log(`Indonesia valid px: ${idCnt}/${idTot} (0.0%) mean: null`);
      console.log('C2');
      return;
    }

    const auMeanVal = results.auMean;
    const idMeanVal = results.idMean;
    const auPct = (auCnt / auTot) * 100.0;
    const idPct = (idCnt / idTot) * 100.0;

    // Calculation failure checks
    function invalid(v) {
      return v === null || isNaN(v) || v < 0 || v > 1.0;
    }
    if (invalid(auMeanVal) || invalid(idMeanVal)) {
      console.log(`Australia valid px: ${auCnt}/${auTot} (${auPct.toFixed(1)}%) mean: ${auMeanVal}`);
      console.log(`Indonesia valid px: ${idCnt}/${idTot} (${idPct.toFixed(1)}%) mean: ${idMeanVal}`);
      console.log('C3');
      return;
    }

    console.log(`Australia valid px: ${auCnt}/${auTot} (${auPct.toFixed(1)}%) mean: ${auMeanVal.toFixed(4)}`);
    console.log(`Indonesia valid px: ${idCnt}/${idTot} (${idPct.toFixed(1)}%) mean: ${idMeanVal.toFixed(4)}`);

    const diff = auMeanVal - idMeanVal;
    console.log(`Diff (AU - ID): ${diff.toFixed(5)}`);

    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    try { console.log(`Error: ${err.message || err}`); } catch (_) {}
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
